def batch(on, accounts):
    notices = []
    for account in accounts:
        row = notice(account)
        if row["send_on"] == on:
            notices.append(row)
    total_due_cents = sum(row["amount_due_cents"] for row in notices)
    return {"on": on, "notices": notices, "total_due_cents": total_due_cents}


def handle(request):

if request.get("command") == "export":
    return export(request["accounts"])
if request.get("command") == "batch":
    return batch(request["on"], request["accounts"])
return {"error": "unknown_command"}

    def test_batch_includes_only_accounts_sent_on_the_requested_day(self):
        self.assertEqual(
            self.call({"command": "batch", "on": "2026-04-01", "accounts": [
                {"customer_id": "M-17", "renewal_on": "2026-04-15", "plan_cents": 19999, "completed_years": 3, "autopay": False},
