            ], "total_due_cents": 17000},
        )

    def test_batch_with_no_matches_returns_empty_notices(self):
        self.assertEqual(
            self.call({"command": "batch", "on": "2026-04-01", "accounts": []}),
            {"on": "2026-04-01", "notices": [], "total_due_cents": 0},
        )

